-- Shared work changes future quotes only; existing ledger entries are untouched.
CREATE TABLE IF NOT EXISTS ion_work_config(id boolean PRIMARY KEY DEFAULT true CHECK(id),baseline_us bigint NOT NULL CHECK(baseline_us>=0),basis text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by integer REFERENCES users(id));
INSERT INTO ion_work_config(id,baseline_us,basis) SELECT true,COALESCE((SELECT p.duration_us FROM ion_time_config c JOIN ion_time_cost_proposals p ON p.id=c.free_proposal_id WHERE c.id),0)+COALESCE((SELECT sum(direct_us) FROM ion_time_products WHERE published_at IS NOT NULL),0),'Imported earlier published direct-work estimates plus the free-work estimate once. Historical session timestamps were not recorded.' ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS ion_work_sessions(id uuid PRIMARY KEY,dev_user_id integer NOT NULL REFERENCES ion_dev_accounts(user_id),started_at timestamptz NOT NULL,ended_at timestamptz,description text NOT NULL,source text NOT NULL CHECK(source IN ('manual','agent')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ended_at IS NULL OR ended_at>=started_at));
CREATE INDEX IF NOT EXISTS ion_work_sessions_dev_idx ON ion_work_sessions(dev_user_id,started_at);
CREATE UNIQUE INDEX IF NOT EXISTS ion_work_sessions_active_idx ON ion_work_sessions(dev_user_id) WHERE ended_at IS NULL;
CREATE TABLE IF NOT EXISTS ion_work_revisions(id uuid PRIMARY KEY,actor_id integer NOT NULL REFERENCES users(id),session_id uuid REFERENCES ion_work_sessions(id),before_value jsonb NOT NULL,after_value jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
